bash -c 'nvidia-smi; gcnt=$(nvidia-smi -L | wc -l); for ((g=0; g<gcnt; g++)); do mapfile -t pids < <(nvidia-smi -q -i "$g" | awk "/Process ID/ {print \$4}"); [ ${#pids[@]} -eq 0 ] && continue; echo "+-------gpu $g-----------------------------------------------------------------+"; s=0; for pid in "${pids[@]}"; do mem=$(nvidia-smi -q -i "$g" | grep -A 4 "Process ID.*$pid" | grep "Used GPU Memory" | awk "{print \$5\$6}"); num=$(echo "$mem" | sed "s/MiB//"); cn="N/A"; if [ -f "/proc/$pid/cgroup" ]; then cid=$(awk -v FS="/" "{print \$NF}" "/proc/$pid/cgroup" | sed "s/\.scope$//" | sed "s/^docker-//" | cut -c 1-12 | head -n 1); if [ -n "$cid" ]; then name=$(docker inspect --format "{{.Name}}" "$cid" 2>/dev/null | sed "s/^\///"); [ -n "$name" ] && cn="[docker]$name"; fi; if [ "$cn" = "N/A" ]; then svc=$(grep -o "[^/]*\.service" "/proc/$pid/cgroup" | head -n 1); [ -n "$svc" ] && cn="[systemd]$svc"; fi; fi; printf "%-4s %-8s %-12s %s\n" "$g" "$pid" "$mem" "$cn"; s=$((s + num)); done; echo "Used GPU Memory Sum=${s} MiB"; done; echo "+-------all-------------------------------------------------------------------+"; nvidia-smi --query-gpu=timestamp,driver_version,name,index,memory.total,memory.used,memory.free,temperature.gpu,utilization.memory,pstate --format=csv; echo "+-----------------------------------------------------------------------------+"'
